\[
\begin{aligned}
\frac{\partial}{\partial x}
&=(\cos\theta)\frac{\partial}{\partial r}
+\left(\frac{-\sin\theta}{r}\right)\frac{\partial}{\partial\theta}
+(0)\frac{\partial}{\partial z}\\
\frac{\partial}{\partial y}
&=(\sin\theta)\frac{\partial}{\partial r}
+\left(\frac{\cos\theta}{r}\right)\frac{\partial}{\partial\theta}
+(0)\frac{\partial}{\partial z}\\
\frac{\partial}{\partial z}
&=(0)\frac{\partial}{\partial r}
+(0)\frac{\partial}{\partial\theta}
+(1)\frac{\partial}{\partial z}
\end{aligned}
\]

\[
\begin{aligned}
\frac{\partial}{\partial r}
&=(\cos\theta)\frac{\partial}{\partial x}
+(\sin\theta)\frac{\partial}{\partial y}
+(0)\frac{\partial}{\partial z}\\
\frac{\partial}{\partial\theta}
&=(-r\sin\theta)\frac{\partial}{\partial x}
+(r\cos\theta)\frac{\partial}{\partial y}
+(0)\frac{\partial}{\partial z}\\
\frac{\partial}{\partial z}
&=(0)\frac{\partial}{\partial x}
+(0)\frac{\partial}{\partial y}
+(1)\frac{\partial}{\partial z}
\end{aligned}
\]
